@@ -0,0 +1,35 @@
+/**
+ * Sanitize HTML content to prevent XSS attacks
+ * Removes dangerous tags and attributes while preserving safe content
+ */
+export function sanitizeHTML(html: string): string {
+  // Create a temporary DOM element
+  const tempDiv = document.createElement("div");
+  
+  // Set innerHTML - this will parse and escape dangerous content
+  tempDiv.innerHTML = html;
+  
+  // Remove script tags and event handlers
+  const scripts = tempDiv.querySelectorAll("script, iframe, object, embed");
+  scripts.forEach((el) => el.remove());
+  
+  // Remove dangerous attributes
+  const elements = tempDiv.querySelectorAll("*");
+  elements.forEach((el) => {
+    const attrs = Array.from(el.attributes);
+    attrs.forEach((attr) => {
+      if (
+        attr.name.startsWith("on") || // event handlers
+        attr.name === "srcdoc" ||
+        attr.name === "formaction" ||
+        attr.name === "action"
+      ) {
+        el.removeAttribute(attr.name);
+      }
+    });
+  });
+  
+  // Return sanitized HTML
+  return tempDiv.innerHTML;
+}
