+/**
+ * Sanitizes URLs to prevent XSS attacks via javascript: protocol
+ * @param {string} url - The URL to sanitize
+ * @returns {string|null} - Sanitized URL or null if invalid
+ */
+export function sanitizeURL(url) {
+  if (typeof url !== 'string') {
+    return null
+  }
+
+  const trimmedURL = url.trim()
+
+  // Block javascript: protocol (case-insensitive)
+  if (/^javascript\s*:/.test(trimmedURL)) {
+    return null
+  }
+
+  // Block data: protocol with script content
+  if (/^data\s*:text\/html/.test(trimmedURL)) {
+    return null
+  }
+
+  // Block vbscript: protocol
+  if (/^vbscript\s*:/.test(trimmedURL)) {
+    return null
+  }
+
+  // Validate URL format
+  try {
+    new URL(trimmedURL)
+    return trimmedURL
+  } catch (e) {
+    // If not a valid URL, check if it's a relative path
+    if (trimmedURL.startsWith('/') || trimmedURL.startsWith('./') || trimmedURL.startsWith('../')) {
+      return trimmedURL
+    }
+    return null
+  }
+}
