+/**
+ * Validates that a URL points to an allowed Firebase domain
+ * to prevent session token synchronization attacks
+ */
+export function isAllowedDomain(url: string): boolean {
+  try {
+    const urlObj = new URL(url);
+    const allowedPatterns = [
+      /\.firebaseio\.com$/,
+      /\.firebaseapp\.com$/,
+      /\.googleapis\.com$/,
+    ];
+
+    return allowedPatterns.some((pattern) => pattern.test(urlObj.hostname));
+  } catch {
+    return false;
+  }
+}
+
+/**
+ * Validates that a URL is a valid HTTPS URL
+ */
+export function isValidHttpsUrl(url: string): boolean {
+  try {
+    const urlObj = new URL(url);
+    return urlObj.protocol === 'https:';
+  } catch {
+    return false;
+  }
+}

