+// CVE-2023-39532 fix: Validate module specifiers to prevent arbitrary code execution
+// This prevents dynamic import after spread operator from accessing host modules
+
+const VALID_MODULE_SPECIFIER_PATTERN = /^(\.\.?\/|[a-zA-Z0-9@/._-]+)$/;
+const FORBIDDEN_PATTERNS = [
+  /^data:/i,
+  /^javascript:/i,
+  /^file:/i,
+  /^blob:/i,
+  /^http:\/\//i,
+  /^https:\/\//i,
+  /%00/,
+  /%2e%2e/i,
+  /%2f/i,
+  /%5c/i,
+];
+
+export function validateModuleSpecifier(specifier) {
+  if (typeof specifier !== 'string') {
+    throw new TypeError('Module specifier must be a string');
+  }
+
+  // Reject empty specifiers
+  if (specifier.length === 0) {
+    throw new TypeError('Module specifier cannot be empty');
+  }
+
+  // Reject data URLs and other dangerous protocols
+  for (const pattern of FORBIDDEN_PATTERNS) {
+    if (pattern.test(specifier)) {
+      throw new TypeError(`Module specifier contains forbidden protocol: ${specifier}`);
+    }
+  }
+
+  // Reject null bytes and path traversal attempts
+  if (specifier.includes('\0') || specifier.includes('..')) {
+    throw new TypeError('Module specifier contains invalid characters');
+  }
+
+  // Validate basic format
+  if (!VALID_MODULE_SPECIFIER_PATTERN.test(specifier)) {
+    throw new TypeError('Invalid module specifier format');
+  }
+}
