+/**
+ * Safe expression evaluation to prevent code injection vulnerabilities
+ * CVE-2021-42057 fix: Replaces eval with restricted Function constructor
+ */
+
+export function safeEvaluate(expression: string, context: any): any {
+    // Block dangerous patterns
+    if (!isValidExpression(expression)) {
+        throw new Error("Invalid expression: code injection detected");
+    }
+    
+    // Extract only allowed properties from context
+    const allowedProperties = Object.keys(context);
+    const safeContext = Object.fromEntries(
+        allowedProperties.map(key => [key, context[key]])
+    );
+    
+    // Use Function constructor with explicit parameter list
+    const fn = new Function(...allowedProperties, `return ${expression}`);
+    return fn(...allowedProperties.map(key => safeContext[key]));
+}
+
+function isValidExpression(expr: string): boolean {
+    // Block dangerous patterns that could lead to code injection
+    const dangerousPatterns = [
+        /eval\s*\(/i,
+        /Function\s*\(/i,
+        /require\s*\(/i,
+        /import\s*\(/i,
+        /process\s*\./i,
+        /global\s*\./i,
+        /__proto__/i,
+        /constructor/i,
+        /prototype/i,
+        /__defineGetter__/,
+        /__defineSetter__/
+    ];
+    
+    return !dangerousPatterns.some(pattern => pattern.test(expr));
+}
+
+export default safeEvaluate;

